/**
 * Reproduces typing in a value-bound tooltip, as generated by UI5InputMarkdown.
 */
export async function runUI5MarkdownTooltipRegression() {
    await new Promise(fnResolve => sap.ui.getCore().attachInit(fnResolve));
    const [Markdown, JSONModel] = await new Promise((fnResolve, fnReject) => {
        sap.ui.require([
            'exface/ui5Custom/Markdown', 'sap/ui/model/json/JSONModel',
            'libs/exface/markian/editor'
        ], (...aModules) => fnResolve(aModules), fnReject);
    });
    const oModel = new JSONModel({markdown: ''});
    const oControl = new Markdown('ui5-markian-tooltip-regression', {
        value: {path: '/markdown'},
        tooltip: {path: '/markdown', formatter: sValue => sValue || ''},
        height: '300px'
    }).setEditorConfig({options: {initialMode: 'visual', sidebarVisible: false}});
    /**
     * A healthy container alone does not prove that typing retained focus and content.
     */
    function check(bCondition, sMessage) {
        if (!bCondition) throw new Error(sMessage);
    }
    try {
        oControl.setModel(oModel);
        oControl.placeAt('fixtures');
        sap.ui.getCore().applyChanges();
        await oControl._oEditor.ready;
        const oInitialEditor = oControl._oEditor;
        const domEditable = oControl.getDomRef().querySelector('.markian-visual [contenteditable="true"]');
        // Browser automation supplies genuine key events to this surface.
        await new Promise((fnResolve, fnReject) => {
            window.ui5MarkdownTooltipFixture = {element: domEditable, finish: fnResolve, fail: fnReject};
        });
        sap.ui.getCore().applyChanges();
        check(oControl._oEditor === oInitialEditor, 'Typing rebuilt the editor through its tooltip binding');
        check(document.activeElement === domEditable, 'Typing lost focus');
        check(oModel.getProperty('/markdown') === 'Focus check', 'Typing did not retain the complete text');
        check(oControl.getDomRef().title === 'Focus check', 'The value-bound tooltip did not update');
        oControl.setValueStateText('Validation error').setValueState('Error');
        oModel.setProperty('/markdown', 'Host update');
        sap.ui.getCore().applyChanges();
        check(oControl._oEditor === oInitialEditor, 'Host tooltip updates rebuilt the editor');
        check(oControl.getDomRef().title === 'Validation error', 'Tooltip updates hid validation feedback');
        oControl.setValueState('None');
        check(oControl.getDomRef().title === 'Host update', 'Clearing validation lost the current tooltip');
        return ['typing retains focus, complete source and editor instance', 'bound tooltips update without hiding validation'];
    } finally {
        delete window.ui5MarkdownTooltipFixture;
        oControl.destroy();
        oModel.destroy();
    }
}
